formulas.expression:
/*For the Support Option check on a Case's related contact, Japanese language is the ultimate concern. If Support Option contains "Japanese" we need to route those accordingly. If Support Option is blank, or anything else, we can route normally through Omni-Channel, which is why the default value here is English. */

IF(
AND(
NOT(ISBLANK({!IncomingRecord.Contact.Support_Option__c})), 
INCLUDES({!IncomingRecord.Contact.Support_Option__c}, "Support Japanese")
), "Japan",
IF(
AND(
NOT(ISBLANK({!IncomingRecord.Contact.Support_Option__c})), 
INCLUDES({!IncomingRecord.Contact.Support_Option__c}, "Support English")
), "English", ""
))
